# -*- coding: utf-8 -*-
"""Swahili text for the Rule page. TEXT = {key: translated inner HTML}."""
TEXT = {
"k34706326": "Juu ya kanuni ya sala",
"kc1ba8633": "Yale ambayo vyanzo vya Kanisa vinasema juu ya kiasi cha kusali, na juu ya kusali kadiri ya uwezo wa kila mtu. Ukurasa huu unatoa vyanzo hivyo; hauviongezei ushauri.",
"ka7965ff8": "<strong>Soma haya kwanza.</strong> Kila kitu kilicho katika Plithos ni marejeo, si kipimo chako. Sala, kanuni ya kufunga, saa za sala na taratibu za ibada zimewekwa hapa kamili kwa sababu ni urithi wa Kanisa na yapasa yapatikane kwa kila mtu. Kuziweka kamili si kusema kwamba yeyote analazimika kuzishika zote.",
"kef5c7431": "Kanuni unayoishika inawekwa na baba yako wa kiroho, kadiri ya ujuzi wako, nguvu zako na hali zako. Hakuna kitu katika tovuti hii kinachopita hayo, wala hakuna neno hapa linalomhukumu anayesali pungufu ya yaliyochapishwa. Anayesema Baba Yetu mara tatu kwa siku na kuisema kwa moyo, anaishika kanuni ambayo Kanisa lilitoa katika karne ya kwanza.",
"kfd250c56": "Ukurasa huu unatoa yale ambayo vyanzo vinasema, wala hauongezi ushauri wake. Pale ambapo sentensi haina rejeo, ni maelezo juu ya tovuti hii, si maelekezo juu ya sala yako. Uongozi ni wa padre wako, anayeujua maisha yako; tovuti hii haiyajui.",
"kd06d4f8a": "Kanuni ya kale kabisa ilikuwaje kwa kweli",
"kc90dad01": "Kitabu cha kale kabisa cha mwenendo wa Kikristo kilichosalia ni Didache, cha mwaka 100 hivi. Kanuni yake ya sala ni Baba Yetu mara tatu kwa siku.",
"kadda83fe": "Mara tatu kwa siku salini hivi.",
"k513c7122": "Didache 8 &middot; tafsiri ya M. B. Riddle, 1886 &middot; <a href=\"/library#work=didache\">soma katika Maktaba</a>",
"k355facce": "Andiko hilo hilo, sura mbili nyuma, linatamka kanuni ya kiasi waziwazi, wala si ulaini wa nyakati hizi bali ni jambo la kale kabisa ambalo Kanisa liliandika juu ya suala hili:",
"k0133b448": "Kwa maana ukiweza kubeba nira yote ya Bwana, utakuwa mkamilifu; lakini kama huwezi, fanya lile uwezalo.",
"kec4ccf0b": "Didache 6 &middot; tafsiri ya M. B. Riddle, 1886 &middot; <a href=\"/library#work=didache\">soma katika Maktaba</a>",
"ka800cdac": "Taratibu kamili zaidi za sala zilizomo katika vitabu vya sala vya baadaye zilikua baada ya hili. Didache ni kanuni ya kale kabisa iliyoandikwa ambayo Kanisa linayo, na haya ndiyo inayodai.",
"kc8529ac1": "Wingi si kipimo",
"k605c07f5": "Mtakatifu Yohane Kasiani, akiandika mafundisho ya mababa wa Misri mwanzoni mwa karne ya tano, anaonya juu ya kuhesabu sala kwa nyakati ambazo mtu huzitenga kwa ajili yake:",
"kda219ca8": "Kwa maana asali kidogo mno yule aliyezoea kusali tu katika nyakati anazopiga magoti.",
"k87ef1fff": "Mtakatifu Yohane Kasiani, Mazungumzo 10.14 &middot; tafsiri ya Edgar C. S. Gibson &middot; <a href=\"/library#work=cassian-conferences\">soma katika Maktaba</a>",
"k6f06dcb5": "Basi kipimo cha sala kwa Kasiani ni kipana kuliko nyakati zilizowekwa, na neno hili linaelekezwa kwa wale wanaoifungia humo. Si yeye anayeleta wazo hili. Mtume alikuwa amekwisha kutoa kanuni katika umbo ambalo saa yoyote haiwezi kulishika:",
"k9d16dd79": "Salini daima, mkiomba msaada wa Mungu. Salini kila wakati kwa nguvu ya Roho. Kesheni bila kuchoka mkisali kwa ajili ya watu wote wa Mungu.",
"kd45e4afe": "Waefeso 6:18",
"k8ff6957a": "Na kwa kifupi zaidi: <em>salini bila kukoma</em> (1 Wathesalonike 5:17). Kanuni ya nyakati zilizowekwa inahudumia hilo; hailimalizi.",
"k94022491": "Ni mpangilio, si ngazi",
"k6f5ac9c2": "Yafuatayo si madaraja yanayowekwa na Plithos. Ni mpangilio wa yale ambayo vyanzo na vitabu vilivyopokewa vinayo, kwa kadiri ya kiasi ambacho kila kimoja kinaomba kutoka katika siku. <strong>Ni lipi kati ya haya linalomfaa mtu fulani, ni swali kwa baba yake wa kiroho, si kwa ukurasa huu.</strong>",
"kbd0070ec": "Si ngazi, na kipengele cha kwanza ndicho sababu yenyewe. Sala ya Yesu iko mbele kwa sababu inaomba kidogo kabisa kutoka katika hali za mtu, si kwa sababu inaomba kidogo kabisa kutoka kwa mtu mwenyewe. Sala hiyo hiyo ndiyo ambayo mababa wa ukimya wanaiita sala yote, na ndiyo wanayopewa waliokwenda mbali zaidi badala ya kila kilichoandikwa. Inasimama pande zote mbili kwa wakati mmoja.",
"kec53651e": "Sala ya Yesu",
"kd76e85df": "Wakati hakuna muda, wala kitabu, wala utulivu - safarini, kazini, katika ugonjwa, usipoweza kusimama wala kusema kwa sauti",
"k15c8fcc6": "Sala ya Yesu katika umbo lake kamili: <em>Bwana Yesu Kristo, Mwana wa Mungu, unirehemu mimi mwenye dhambi.</em> Pale ambapo hata hiyo ni nyingi, Mababa wanaruhusu maumbo mafupi zaidi - <em>Bwana Yesu Kristo, unirehemu</em>, au kwa kifupi <em>Bwana, rehema</em>. Haihitaji kitabu, wala kusimama, wala sauti, na inaweza kubebwa katika siku ya kawaida ya kazi.",
"k433c6e1a": "<a href=\"/prayers#s=heart\">Sala ya Yesu, na ushauri wa Mababa juu ya kuishika</a>",
"k0607d349": "Inakuja kwanza kwa sababu inadumu katika kila hali, si kwa sababu ni ndogo kuliko yote yaliyo hapa. Kasiani, Mazungumzo 10.14: \"asali kidogo mno yule aliyezoea kusali tu katika nyakati anazopiga magoti.\"",
"k4fbd7571": "Baba Yetu, mara tatu kwa siku",
"kccf34183": "Kanuni maalum katika nyakati maalum, inapowezekana",
"k6c98a369": "Kanuni ya kitabu cha kale kabisa cha Kikristo tulicho nacho. Ni kanuni ndogo, lakini ni kanuni ya nyakati maalum, na hivyo inaomba zaidi kutoka katika siku iliyokatika kuliko inavyoomba Sala ya Yesu.",
"kb80095bf": "Didache 8.",
"k73f947ac": "Kanuni ya Mtakatifu Serafimu wa Sarov",
"kbeb11458": "Kwa wale ambao kazi yao haiachi nafasi ya kanuni ndefu zaidi",
"kba90cd4c": "Ukiamka, ukisimama mbele ya sanamu takatifu: Baba Yetu mara tatu, <em>Bikira Mzazi-Mungu, furahi</em> mara tatu, na Kanuni ya Imani mara moja. Kisha kazini, ukisema Sala ya Yesu kwa unyamavu asubuhi yote, na <em>Mzazi-Mungu Mtakatifu Kabisa, uniokoe</em> alasiri. Kanuni fupi hiyo hiyo tena kabla ya kulala.",
"k6464f90a": "Mtakatifu Serafimu aliitoa kwa wafanyakazi na wenye nyumba ambao hawakuweza kushika sala kamili zaidi za asubuhi na jioni, wala hakuiona kama upole ambao mtu apaswa kuukua na kuuacha. Ni kanuni ya sala maalum katika nyakati maalum, ikiunganishwa na sala inayopita katika siku nzima ya kazi, na ndiyo sababu iko hapa wala si chini zaidi.",
"kc823332f": "Mtakatifu Serafimu wa Sarov, katika mafundisho yake kwa walei. Sala zenyewe ziko katika ukurasa wa Sala.",
"k3041ac63": "Asubuhi na jioni",
"k225e3ccd": "Kanuni ya kawaida ya kitabu cha sala kwa mlei",
"kf4d2a2e5": "Sala za asubuhi wakati wa kuamka na za jioni kabla ya kulala, zikisemwa kwa makini wala si kwa haraka.",
"k98ad4446": "<a href=\"/prayers#s=daily\">Sala za asubuhi na za jioni</a>",
"k8ad36869": "Mtakatifu Theofani wa Upweke aliona sala za asubuhi na jioni za kitabu cha sala kuwa zinatosha kabisa kwa mlei anayeanza. Ona maelezo katika ukurasa wa Sala kwa ushauri kamili zaidi.",
"k4cecadd4": "Pamoja na Saa",
"kefb7d0a1": "Pale ambapo siku inaruhusu",
"k8fb45542": "Ibada fupi katika mchana wote, kutoka Saa ya Kwanza hadi sala ya usiku.",
"k6b300612": "<a href=\"/prayers#s=hours\">Saa za sala</a>",
"k61610f0a": "Sala tatu za kila siku za Didache ndizo mbegu ya mzunguko huu. Saa kamili zimo katika Horologion.",
"kb3c5ab3d": "Maandalizi ya Komunyo",
"k8dbdf873": "Kabla ya kupokea Siri Takatifu",
"kced3fbfd": "Utaratibu wa Maandalizi, sala mbili zinazosemwa mbele ya kikombe, na shukrani baada yake. Kiasi gani cha Utaratibu kinasemwa, na kama kinashikwa jioni ya awali au asubuhi ya siku hiyo, hutofautiana kwa mapokeo na huwekwa na baba wa kiroho. Ona hapa chini yale ambayo Mababa wanayafanya kuwa sharti halisi la kukaribia.",
"k8f37e928": "<a href=\"/prayers#s=communion\">Sala za Komunyo Takatifu, katika sehemu zake tatu</a>",
"k88dda4ec": "Mwenendo unatofautiana wazi kati ya mapokeo ya Kislavoni na ya Kigiriki, katika maandalizi yanayotarajiwa na katika mara ngapi waamini wanapokea.",
"ka6cba0b8": "Usipoweza kushika kanuni yako",
"k87db3602": "Safari, ugonjwa, kazi ya usiku, watoto wadogo, huzuni na uchovu, vyote hukatiza kanuni. Mambo mawili katika maandiko yaliyotangulia yanagusa hili moja kwa moja.",
"k8dcf4ab6": "<strong>Didache haiwasilishi kanuni kama yote au bila kitu.</strong> Maelekezo yake si kubeba nira yote au bila kitu, bali ni kwamba pale ambapo yote haiwezi kubebwa, \"fanya lile uwezalo\".",
"ka4ac033d": "<strong>Sala haijafungwa katika nyakati za kusimama.</strong> Hii ndiyo nguvu ya neno la Kasiani lililotangulia: anawakemea wale wanaohesabu sala yao kwa nyakati za kupiga magoti tu, na hilo linaingiza katika hesabu ile sala iliyo nje ya nyakati hizo badala ya kuitoa. Sala ya Yesu katika maumbo yake mafupi yaliyopokewa haihitaji kitabu, wala hali ya mwili, wala sauti.",
"k1c9eeaa9": "Yale ambayo Mababa wanayafanya kuwa sharti la kukaribia",
"keac4f2df": "Utaratibu wa Maandalizi ni wema wa kweli na urithi wa kweli. Si huo unaomwezesha mtu kupokea. Katika hili Mababa wanasema waziwazi, nao waliandika kabla ya kuwepo utaratibu wowote wa maandalizi uliochapishwa.",
"kc356b366": "Mtakatifu Yohane Krisostomo, akihubiri juu ya Waebrania, anachukua hasa swali la mara ngapi na kiasi gani, na anakataa kulijibu kwa maneno hayo:",
"kce69ff57": "Basi ni nini? Tuwakubali kina nani? Wale wanaopokea mara moja kwa mwaka? Wale wanaopokea mara nyingi? Wale wanaopokea mara chache? Si wale wa mara moja, wala wale wa mara nyingi, wala wale wa mara chache, bali wale wanaokaribia kwa dhamiri safi, kwa moyo safi, kwa maisha yasiyo na lawama. Hao na wakaribie daima; lakini wale wasio hivyo, hata mara moja isiwe.",
"k2d880e69": "Mtakatifu Yohane Krisostomo, Mahubiri ya 17 juu ya Waebrania &middot; tafsiri ya Frederic Gardiner &middot; <a href=\"/library#work=chrysostom-homilies-hebrews\">soma katika Maktaba</a>",
"k3448180a": "Kipimo anachokitaja Krisostomo ni hali ya dhamiri. Hataji idadi yoyote, wala ya komunyo wala ya sala zinazosemwa kabla, naye anaweka kando swali la mara ngapi kama swali lisilo sahihi.",
"k4bc3e896": "Mtakatifu Yohane Kasiani anashughulikia nusu ile nyingine, na kichwa cha sura kinalisema wazi: <em>kwamba ingawa tunakiri kuwa hatuwezi kuwa bila dhambi, hata hivyo hatupaswi kujitenga na Komunyo ya Bwana.</em>",
"k3620ced2": "Lakini hatupaswi kujitenga na Komunyo ya Bwana kwa sababu tunajikiri kuwa wenye dhambi, bali tuikimbilie kwa bidii zaidi kwa uponyaji wa roho zetu na utakaso wa nafsi zetu, na tutafute dawa ya majeraha yetu kwa unyenyekevu wa nia na kwa imani, tukijiona hatustahili kupokea neema kubwa hivyo.",
"k99dd8e07": "Vinginevyo hatuwezi kupokea Komunyo kwa ustahili hata mara moja kwa mwaka, kama wanavyofanya wengine wanaoishi katika nyumba za watawa na wanaoiona heshima na utakatifu na thamani ya siri za mbinguni kwa jinsi kwamba wanadhani kuwa hakuna mtu ila watakatifu na wasio na doa apaswaye kuthubutu kuzipokea, wala hawadhani zaidi kwamba zingewafanya watakatifu na safi kwa kuzipokea. Na kwa hilo wanaanguka katika kujiona na kiburi kikubwa kuliko kile wanachoona wanakiepuka, kwa sababu wakati wanapopokea, wanajiona wanastahili kupokea.",
"kb8b440b1": "Mtakatifu Yohane Kasiani, Mazungumzo 23.21 &middot; tafsiri ya Edgar C. S. Gibson &middot; <a href=\"/library#work=cassian-conferences\">soma katika Maktaba</a>",
"kcab416e7": "Hoja ya Kasiani ni kwamba kujitenga kwa hisia ya kutostahili ndiyo kujiona kukubwa zaidi, kwa kuwa yule anayejitenga hadi awe anastahili anadhania kwamba siku nyingine angekuwa anastahili. Dhidi ya hilo anaweka lile ambalo, kwa neno lake, Siri Takatifu zipo kwa ajili yake: si tuzo kwa waliokwisha kuwa safi, bali njia ambayo kwayo, kwa maneno yake, zingetufanya watakatifu na safi kwa kuzipokea.",
"k1ceaa3c4": "Yale ambayo Kanisa linamfanya mpokeaji ayaseme juu yake mwenyewe",
"k15496498": "Hili si kushusha kipimo. Hiki ndicho kipimo, na Kanisa linakiweka katika kinywa cha kila anayekaribia. Ungamo linalosemwa mbele ya kikombe, kwa sauti, na kusanyiko lote, halisemi kwamba anayelisema amefika:",
"kffb87ae9": "Naamini, Bwana, na ninaungama kwamba Wewe ndiwe kweli Kristo, Mwana wa Mungu aliye hai, uliyekuja ulimwenguni kuwaokoa wenye dhambi, ambao kati yao mimi ni wa kwanza.",
"kd40a122c": "Sala kabla ya kupokea &middot; kwa mujibu wa 1 Timotheo 1:15 &middot; <a href=\"/prayers#s=communion\">soma katika kitabu cha sala</a>",
"k91d95d94": "Maneno ya Mtume mwenyewe ni <em>Kristo Yesu alikuja ulimwenguni kuwaokoa wenye dhambi. Nami ni mkosefu zaidi kuliko hao wote</em>, na Kanisa halikuyaacha katika waraka. Liliyaweka mbele ya kikombe na kumpa kila apokeaye ayaseme kwa nafsi ya kwanza, siku anayopokea. Watakatifu ni wale waliosema sentensi hiyo na kuisema kwa moyo, si wale waliofika mahali ambapo iliacha kuwahusu. Neema hutolewa; kinachotakiwa kwetu ni kwamba tujibu, tuzishike amri tulizopewa, na tuendelee kujibu baada ya kushindwa kuzishika.",
"kf78cb40a": "Hili linamaanisha nini kwa vitendo",
"k87e5b047": "<strong>Utaratibu si miongoni mwa masharti ya kikanoni.</strong> Hakuna kanuni ya Kanisa inayoudai kabla ya kupokea, na mfuatano uliochapishwa ni wa baadaye kuliko kanuni; kiasi gani chake kinasemwa huwekwa na baba wa kiroho.",
"k0e542bbd": "<strong>Lile ambalo mapokeo yanalitaja kweli</strong> mbele ya kikombe ni dhamiri isiyotulia katika dhambi isiyotubiwa, amani na jirani, kufunga kwa ajili ya Ekaristi, na utii kwa baba wa kiroho kuhusu kuungama. Kasiani anashughulikia moja kwa moja hali ya yule aliyejitenga kwa sababu ya kutostahili, katika kifungu kilichotangulia; Krisostomo anashughulikia yule anayehesabu kwa idadi.",
"k21c606eb": "<strong>Kufunga kwa ajili ya Ekaristi ni jambo la kikanoni, si la desturi tu.</strong> Sheria ya Afrika ilikidai, ikiruhusu ubaguzi mmoja tu katika mwaka, siku ile ambayo Karamu ya Bwana inakumbukwa:",
"k253a3d17": "Kwamba Siri za Altare zisiadhimishwe ila na wale waliofunga, isipokuwa kumbukumbu ile moja ya mwaka ya kuadhimisha Karamu ya Bwana; kwa maana ikiwa ukumbusho wa baadhi ya waliolala, maaskofu au wengine, wapaswa kufanywa alasiri, na ufanywe kwa sala tu, ikiwa wale wanaohudumu wamekwisha kula.",
"kb289f398": "Sheria ya Afrika (419), kanuni ya 41 &middot; tafsiri ya Henry R. Percival, 1900 &middot; <a href=\"/library#work=canons-ecumenical\">soma katika Maktaba</a>",
"kfd9e4371": "Mtaguso wa Trullo ulichukua kanuni hiyo na kuondoa ubaguzi ule:",
"k97125890": "Kanuni ya Sinodi ya Karthago inasema kwamba siri takatifu za altare hazipaswi kufanywa ila na wale waliofunga, isipokuwa siku moja katika mwaka ambayo Karamu ya Bwana inaadhimishwa. Wakati ule, labda kwa sababu ya hali fulani zilizolinufaisha Kanisa katika maeneo yale, hata Mababa watakatifu wenyewe walitumia upole huu. Lakini kwa kuwa hakuna kinachotusukuma kuacha ushikaji sahihi, tunaamuru kwamba mapokeo ya kitume na ya kibaba yafuatwe; nasi tunaeleza kwamba si sawa kufungua funga katika siku ya tano ya juma la mwisho la Kwaresima, na hivyo kuidhalilisha Kwaresima yote.",
"k5c17110d": "Mtaguso wa Trullo, ule wa Tano-Sita (692), kanuni ya 29 &middot; tafsiri ya Henry R. Percival, 1900 &middot; <a href=\"/library#work=canons-ecumenical\">soma katika Maktaba</a>",
"k4b650236": "Kile ambacho kanuni zinadai ni kufunga. Kukihesabu tangu usiku wa manane wa siku iliyotangulia ni desturi inayokibeba, nayo ni mwenendo wa kawaida katika kila mamlaka. Pale ambapo Liturujia inaadhimishwa jioni, kama ile ya Vipawa Vilivyotangulia Kutakaswa na kama zinavyoweza kuwa Liturujia za Kuzaliwa kwa Bwana, Epifania, Alhamisi Kuu na Jumamosi Kuu, kipindi kinawekwa na askofu badala ya kuhesabiwa tangu usiku wa manane. Dawa inayopaswa kunywewa, ugonjwa, mimba, utoto na uzee mkubwa hushughulikiwa na baba wa kiroho. Kuuliza si sawa na kusamehewa, wala hakuna kati ya hivyo kinachotoa sababu ya kukaa mbali na kikombe.",
"kc182b483": "<strong>Sala mbili zinazosemwa mbele ya kikombe</strong> - \"Naamini, Bwana, na ninaungama\" na \"Karamu Yako ya Siri\" - zinasemwa kwa sauti pamoja na kusanyiko lote katika parokia nyingi.",
"kaebd6892": "Kanuni ni za kimonaki kwa umbo; maisha zinayoyaomba si ya kimonaki",
"keedea2a4": "Karibu kila kanuni maalum iliyochapishwa katika kitabu cha sala ilipata umbo lake la sasa katika nyumba ya watawa, na ndiyo sababu maandalizi yanaweza kusomeka kana kwamba yanamwelekea mtu mwingine. Pingamizi hili ni la kale kiasi kwamba Mtakatifu Yohane Krisostomo analiweka katika vinywa vya wasikilizaji wake kabla ya kulijibu:",
"k3f765fe1": "Mimi si mmoja wa watawa, utasema, bali nina mke na watoto na uangalizi wa nyumba. Kumbe hilo hasa ndilo lililoharibu yote, kudhani kwako kwamba kusoma Maandiko Matakatifu ni kwa hao tu, hali wewe unayahitaji zaidi sana kuliko wao. Kwa maana wale wanaokaa ulimwenguni na kupokea majeraha kila siku, hao ndio wenye uhitaji mkubwa zaidi wa dawa.",
"kebad4fa3": "Mtakatifu Yohane Krisostomo, Mahubiri ya 2 juu ya Mathayo &middot; tafsiri ya George Prevost &middot; <a href=\"/library#work=chrysostom-homilies-matthew\">soma katika Maktaba</a>",
"k5eee983b": "Anasema jambo lilo hilo juu ya namna ya maisha yenyewe, naye analisema kama kukataa kuifanya jangwa kuwa sheria:",
"k00cd498f": "Sifanyi sheria kwamba mkalie milima na majangwa, bali kwamba muwe wema na wenye busara na wasafi, mkikaa katikati ya mji.",
"kc7ddce00": "Mtakatifu Yohane Krisostomo, Mahubiri ya 7 juu ya Mathayo &middot; tafsiri ya George Prevost &middot; <a href=\"/library#work=chrysostom-homilies-matthew\">soma katika Maktaba</a>",
"k99a23dda": "Na katika mahubiri juu ya Warumi anachukua wazo kwamba maisha ya kawaida ni anwani isiyo sahihi ya amri, akiliona kama shtaka dhidi ya imani wala si maelezo yake:",
"k91017238": "Kwa maana kama hakuna uwezekano kwa yule anayeishi katikati ya miji kuwa mwanafunzi, hilo ni shtaka zito dhidi ya mwenendo huu, yaani kwamba tunapaswa kuiacha miji na kukimbilia majangwani. Lakini nionyeshe mtu aliye na mke, na watoto, na jamaa, na hata hivyo anatafuta hekima. Basi tuseme nini juu ya haya yote? Je, hatupaswi kuinamisha vichwa vyetu na kuona haya? Kwa maana Kristo hakutupa amri ya namna hiyo; bali ni ipi? Nuru yenu na iangaze mbele ya watu, si milima, wala majangwa, wala nyika, wala mahali pa mbali.",
"kafb2fb07": "Mtakatifu Yohane Krisostomo, Mahubiri ya 26 juu ya Warumi &middot; tafsiri ya J. B. Morris na W. H. Simcox &middot; <a href=\"/library#work=chrysostom-homilies-romans\">soma katika Maktaba</a>",
"ke1ee6e3e": "Anajihadhari, katika sentensi inayofuata, asisomwe kama anayewadharau watawa: anasema kwamba anena \"si kwa kuwatukana wale walioichukua milima, bali kwa kuwaombolezea wale wanaokaa mijini, kwa sababu wameifukuza fadhila kutoka humo.\" Mtawa anatoa mapenzi yake mwenyewe kwa mzee. Mlei anapewa jambo lilo hilo la kutoa, katika ndoa, katika kazi asiyoichagua, katika uvumilivu ambao nyumba humgharimu, naye anaombwa hilo katika umbo ambalo hakuna kanuni inayoweza kulichapa mapema.",
"ka438020e": "Kufunga, kuungama, na mengineyo ya maandalizi",
"k67ac3841": "Maandalizi si sala tu. Kufunga kwa Jumatano na Ijumaa ni sehemu yake ya kale kabisa, nayo iko katika sura ile ile ya Didache inayotoa kanuni ya sala:",
"ke069eea2": "Lakini funga zenu zisiwe pamoja na wanafiki; kwa maana wao hufunga siku ya pili na ya tano ya juma; bali ninyi fungeni siku ya nne na siku ya Maandalizi (Ijumaa). Wala msisali kama wanafiki, bali kama Bwana alivyoamuru katika Injili yake, salini hivi: Baba yetu uliye mbinguni...",
"k4e4ee152": "Onyo katika kifungu hiki linagusa nusu zote mbili: si kutokufunga, bali kufunga <em>kama wanafiki</em>, na si kutokusali, bali kusali <em>kama wanafiki</em>. Didache inatoa kanuni zote mbili kwa pumzi moja na kuiwekea kila moja masharti kwa namna ile ile.",
"k901f0415": "Kuungama kabla ya komunyo kunatarajiwa katika mapokeo mengine na hakutarajiwi katika mengine, na tofauti hii ni ya zamani wala si suala la ulegevu. Inafaa kuielezea, kwa sababu yule aliyejifunza kujiandaa katika mapokeo moja kisha akajikuta katika parokia ya mapokeo mengine anaweza kwa urahisi kuchukua tofauti ya desturi kama hukumu juu yake.",
"k345e3232": "<strong>Katika Makanisa ya Kislavoni</strong> - Kirusi, Kirusi cha Nje, Kanisa la Othodoksi la Amerika, Kiukreni, Kiserbia - kuungama kunatarajiwa kwa kawaida kabla ya kila komunyo. Maandalizi kwa desturi yanajumuisha kanuni tatu, kwa Mwokozi, kwa Mzazi-Mungu na kwa Malaika Mlinzi, na mara nyingi Akathisto kwa Bwana Yesu Mtamu Kabisa, zaidi ya sala za maandalizi; na kuhudhuria kesha au sala ya jioni ya usiku uliotangulia kunatarajiwa kama sehemu ya maandalizi, si kama ibada ya pekee.",
"k3c46f09c": "<strong>Katika mwenendo wa Kigiriki, Kiantiokia na Kiromania</strong> kuungama mara nyingi kumetenganishwa na komunyo na kunashikwa kwa vipindi vinavyowekwa na baba wa kiroho, mara nyingi katika funga nne. Maandalizi mara nyingi yanamaanisha sala za maandalizi kuliko mkusanyiko wote wa kanuni na akathisto, na ibada ya jioni inahimizwa kwa nguvu bila kufanywa sharti la kupokea.",
"kbf226744": "Zote mbili ni mwenendo uliosimama wa Makanisa mahalia yote, na kila mmoja unashikwa chini ya uongozi wa makleri wa Kanisa hilo. Kanuni ya mtu hapa inatoka kwa baba yake mwenyewe wa kiroho, si kwa maelezo aliyobahatika kuyasoma kwanza.",
"k7edee590": "Neno la mwisho juu ya kiasi",
"k95bf9581": "Kanuni ipo ili tusijitoe kwa uvivu upande mmoja wala tusijilazimishe kupita nguvu zetu upande mwingine. Mtakatifu Theofani wa Upweke alifundisha kwamba njia ina mitaro miwili: kuliani, bidii isiyo na maarifa; kushotoni, uvivu. Kupita kiasi kunamfikisha anayeanza katika uchovu na kukata tamaa anaposhindwa, na katika kiburi anapofaulu. Mtakatifu Ignati Bryanchaninov aliandika kwamba kanuni ipo kwa ajili yako; wewe hupo kwa ajili ya kanuni, bali unaishi kwa ajili ya Bwana, na yakupasa kuhifadhi uhuru wa utambuzi.",
"kd192a6bd": "Anza kidogo. Ni bora kusema sala chache kwa makini kuliko kupita haraka katika nyingi. Ukiwa na baba wa kiroho, shika kanuni anayokupa wala usibadilishe chochote bila baraka yake; kama bado huna, shika kanuni ya wastani inayolingana na nguvu zako na umtafute baba wa namna hiyo. Hakuna kitabu wala ukurasa unaoweza kuchukua nafasi ya baba aliye hai katika Kristo.",
"kb6eb659b": "Yametolewa kwa Mtakatifu Theofani wa Upweke, Kanuni ya Sala, na Mtakatifu Ignati (Bryanchaninov) juu ya kanuni ya sala &middot; <a href=\"/#guide\">pia katika Mwongozo</a>",
"keda0cc2f": "Hakuna kitu katika tovuti hii kilicho mizani ambayo mtu yeyote anapimwa juu yake. Ni maktaba na kalenda.",
"kc89cd31d": "Kanuni ya sala ni kiasi maalum cha sala kinachoshikwa katika nyakati maalum. Ukurasa huu unaeleza yale ambayo vyanzo vya Kanisa vinasema kuhusu kiasi, na maumbo ambayo kanuni huchukua kwa kawaida.",
"k36c2948e": "<strong>Soma haya kwanza.</strong> Kanuni unayoishika inawekwa na baba yako wa kiroho, kulingana na nguvu zako na hali zako. Kilichochapishwa hapa ni urithi, si kipimo ambacho mtu yeyote anapimwa nacho. Anayesema Baba Yetu mara tatu kwa siku na kuisema kwa moyo anaishika kanuni ambayo Kanisa liliitoa katika karne ya kwanza.",
"k530f73b4": "Kanuni inatoka wapi",
"kc776efc1": "Sura mbili kabla, waraka huohuo unataja kipimo, nalo ndilo jambo la kale zaidi ambalo Kanisa liliandika juu ya suala hili:",
"k81f4ff1a": "Kila kilichomo katika vitabu vya sala kilikuja baadaye. Na kanuni ya nyakati maalum huitumikia sala bila kuimaliza: neno la Mtume <em>salini bila kukoma</em> (1 Wathesalonike 5:17) ndilo kipimo pana zaidi, na Mtakatifu Yohana Kasiani, akiwaandika mababa wa Misri, alisema hivyo kwa ukali.",
"k071c623f": "Maumbo ambayo kanuni huchukua",
"k28364d47": "Haya ndiyo maumbo ambayo kanuni ya mlei huwa nayo kwa kawaida, yakipangwa kwa kadiri ya kiasi cha siku ambacho kila moja hukitaka. Si ngazi ya kupanda: la kwanza ndilo ambalo mababa wa hesikia huliita sala nzima, nalo ndilo wanalopewa waliokwenda mbali zaidi badala ya kila kilichoandikwa. <strong>Ni lipi linalokuhusu ni swali kwa baba yako wa kiroho.</strong>",
"kf8b6b4bc": "Sala isiyo na nyakati maalum &middot; wakati hakuna muda, wala kitabu, wala utulivu",
"k491be6c4": "<em>Bwana Yesu Kristo, Mwana wa Mungu, unirehemu mimi mwenye dhambi.</em> Pale ambapo hata hilo ni kubwa mno, Mababa huruhusu maumbo mafupi zaidi - <em>Bwana Yesu Kristo, unirehemu</em>, au kwa urahisi <em>Bwana, urehemu</em>. Haihitaji kitabu, wala kusimama, wala sauti, nayo yaweza kubebwa katika siku nzima ya kazi. Inakuja kwanza kwa sababu inavumilia kila hali, si kwa sababu ndiyo ndogo kuliko yote yaliyo hapa.",
"k2d14e1b1": "Kanuni fupi katika nyakati maalum &middot; Didache",
"k25c1035a": "Sala maalum zilizounganishwa na sala inayoendelea mchana kutwa &middot; kwa wale ambao kazi yao haiwaachii nafasi ya zaidi",
"k5cacd522": "Mtakatifu Serafimu aliitoa kwa wafanyakazi na wenye nyumba ambao hawakuweza kushika sala zilizo kamili zaidi, wala hakuichukulia kuwa upole ambao mtu hukua akiuacha.",
"kc0703990": "Sala za asubuhi wakati wa kuamka na za jioni kabla ya kulala, zikisemwa kwa makini wala si kwa haraka. Mtakatifu Theofani Mtawa aliziona kuwa zatosha kabisa kwa mlei anayeanza.",
"k030dfcd7": "Mzunguko wa kila siku wa ibada &middot; pale siku inaporuhusu",
"k129ba7c3": "Ibada fupi mchana kutwa, kutoka Saa ya Kwanza hadi Ibada ya Usiku. Sala tatu za kila siku za Didache ndizo mbegu ya mzunguko huu; Saa kamili zimo katika Kitabu cha Saa.",
"k6ca85803": "Kanuni ya mara kwa mara &middot; kabla ya kupokea Siri Takatifu",
"kc26de5d2": "Safari, ugonjwa, kazi ya usiku, watoto wadogo, huzuni na uchovu - vyote hukatiza kanuni. Maandiko mawili yaliyotangulia yanahusu jambo hilo moja kwa moja. Didache haiitoi kanuni yake kama yote au bila kitu: pale nira nzima isipoweza kubebwa, \"unachoweza, kifanye\". Na Kasiani anawakemea wale wanaohesabu sala yao kwa nyakati za kupiga magoti tu - jambo linaloingiza katika hesabu sala iliyo nje ya nyakati hizo, wala haliitoi.",
"k892d0484": "Utaratibu wa Maandalizi ni jema la kweli na urithi wa kweli. Lakini si huo unaomfanya mtu aweze kupokea. Mtakatifu Yohana Krisostomo anachukua swali la mara ngapi na kiasi gani, akakataa kulijibu kwa maneno hayo:",
"k74472bee": "Kipimo anachokitaja ni hali ya dhamiri, si hesabu. Mtakatifu Yohana Kasiani anashughulikia nusu nyingine chini ya kichwa cha sura kinachosema jambo hilo waziwazi: <em>kwamba ingawa twakiri kuwa hatuwezi kuwa bila dhambi, hatupaswi hata hivyo kujitenga na Komunyo ya Bwana.</em>",
"k89f08ec2": "Kujiepusha kwa hisia ya kutostahili, asema, ndiko kujidai kukubwa zaidi: yeye ajiepushaye hadi atakapostahili, hudhani kwamba siku nyingine angestahili. Siri Takatifu si tuzo kwa walio safi bali, kwa maneno yake, zingetufanya watakatifu na safi kwa kuzipokea.",
"ke31bdf96": "Hili si kushusha kipimo. Ndicho kipimo chenyewe, na Kanisa hukiweka kinywani mwa kila akaribiaye:",
"kfbddc832": "Maneno ya Mtume mwenyewe ni <em>Kristo Yesu alikuja ulimwenguni awaokoe wenye dhambi, ambao wa kwanza wao ni mimi</em>, na Kanisa halikuyaacha katika waraka: liliyachukua katika ibada, likampa kila mpokeaji ayaseme kwa nafsi ya kwanza, siku anayopokea. Watakatifu ni wale waliosema sentensi hiyo na kuisema kwa moyo, si wale waliofika mahali ambapo ikakoma kuwahusu.",
"kdc0a783e": "<strong>Kile mapokeo yanachokitaja</strong> ni dhamiri isiyotulia katika dhambi isiyotubiwa, amani na jirani, saumu ya Ekaristi, na utii kwa baba wa kiroho kuhusu kuungama.",
"keeb5d497": "<strong>Saumu ya Ekaristi ni ya kikanuni, si ya kimila.</strong> Sheria ya Afrika ya mwaka 419 iliihitaji na kuruhusu ubaguzi mmoja kwa mwaka; Baraza la Trullo lilichukua kanuni hiyo na kuondoa ubaguzi huo:",
"k718a2fab": "Lakini kwa kuwa hakuna kinachotusukuma kuacha ushikaji ulio sahihi, twaamua kwamba mapokeo ya kitume na ya mababa yafuatwe, na twaweka kwamba si haki kuvunja saumu katika siku ya tano ya juma la mwisho la Kwaresima, na hivyo kuiaibisha Kwaresima yote.",
"k2426bb65": "Kile kanuni zinachohitaji ni saumu. Kuihesabu kuanzia usiku wa manane uliopita ndio mila inayoibeba. Pale Liturujia inapoadhimishwa jioni - ya Vipawa Vilivyotangulia Kuwekwa Wakfu, na Liturujia za Kuzaliwa kwa Bwana, Epifania, Alhamisi Kuu na Jumamosi Kuu - kipindi huwekwa na askofu badala ya kuhesabiwa kuanzia usiku wa manane. Dawa zinazopaswa kutumiwa, ugonjwa, ujauzito, utoto na uzee mkubwa hushughulikiwa na baba wa kiroho. Kuuliza si sawa na kusamehewa, wala hakuna lolote kati ya hayo lililo sababu ya kukaa mbali na Kikombe.",
"ka41be440": "Anakataa kuifanya jangwa kuwa sheria - \"siwawekei sheria mkalie milima na majangwa, bali mwe wema na wenye huruma na safi, mkikaa katikati ya mji\" - naye anajihadhari asisomwe kama anayewadharau watawa, akisema kwamba anena \"si kwa kuwatukana wale walioichukua milima, bali kwa kuwaombolezea wale wakaao mijini, kwa sababu wameifukuza fadhila kutoka humo\". Mtawa hukabidhi mapenzi yake kwa mzee. Mlei naye amepewa kitu kilekile cha kukabidhi - katika ndoa, katika kazi asiyoichagua, katika uvumilivu ambao nyumba humgharimu - naye huombwa hivyo kwa namna ambayo hakuna kanuni iwezayo kuichapisha mapema.",
"ke5795f78": "Saumu na kuungama",
"k6602f295": "Maandalizi si sala tu. Saumu ya Jumatano na Ijumaa ndicho kipande chake cha kale zaidi, nayo yamo katika sura ileile ya Didache itoayo kanuni ya sala - ambayo huiwekea mipaka nusu zote mbili kwa namna ileile, ikionya si dhidi ya kutofunga au kutosali, bali dhidi ya kufanya lolote kati ya hayo <em>kama wanafiki</em>.",
"k78388bd9": "Kuungama kabla ya komunyo hutarajiwa katika baadhi ya mapokeo na katika mengine hapana, nayo tofauti hiyo ni ya zamani wala si suala la ulegevu. Yeye aliyejifunza kujiandaa katika pokeo moja kisha akajikuta katika parokia ya lingine, aweza kwa urahisi kuichukua tofauti ya mila kuwa hukumu juu yake.",
}
